    private void btnSubmitPaymentActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnSubmitPaymentActionPerformed
        // TODO add your handling code here:
    // 1. Get data from fields
    String invoiceIdStr = txtInvoiceId.getText().trim();
    String amountStr = txtAmount.getText().trim();
    String reference = txtReference.getText().trim();
    String method = (String) cmbMethod.getSelectedItem();

    // 2. Basic validation
    if (invoiceIdStr.isEmpty() || amountStr.isEmpty() || reference.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, "Please fill in all fields.", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
        return;
    }

    try {
        Long invoiceId = Long.parseLong(invoiceIdStr);
        double amount = Double.parseDouble(amountStr);
        
        // Get the logged-in user's ID
        Long staffId = util.SessionManager.getCurrentUser().getId();

        // 3. Call the Service Layer
        service.PaymentService paymentService = new service.PaymentService();
        
        // This is where the magic happens (Rules 1, 2, and 3 are checked here)
        paymentService.processPayment(invoiceId, staffId, amount, reference, method);

        // 4. Success Message
        javax.swing.JOptionPane.showMessageDialog(this, "Payment recorded successfully!\nReceipt Generated.", "Success", javax.swing.JOptionPane.INFORMATION_MESSAGE);
        
        // Clear fields
        txtInvoiceId.setText("");
        txtAmount.setText("");
        txtReference.setText("");

    } catch (NumberFormatException ex) {
        javax.swing.JOptionPane.showMessageDialog(this, "Invoice ID and Amount must be valid numbers.", "Invalid Input", javax.swing.JOptionPane.ERROR_MESSAGE);
        
    } catch (exception.InvalidAmountException ex) {
        // Rule 3: Invalid Amount
        javax.swing.JOptionPane.showMessageDialog(this, ex.getMessage(), "Payment Failed", javax.swing.JOptionPane.ERROR_MESSAGE);
        
    } catch (exception.DuplicateReferenceException ex) {
        // Rule 2: Duplicate Reference
        javax.swing.JOptionPane.showMessageDialog(this, ex.getMessage(), "Payment Failed", javax.swing.JOptionPane.ERROR_MESSAGE);
        
    } catch (exception.OverpaymentException ex) {
        // Rule 1: Overpayment
        javax.swing.JOptionPane.showMessageDialog(this, ex.getMessage(), "Payment Failed", javax.swing.JOptionPane.ERROR_MESSAGE);
        
    } catch (exception.InvoiceNotFoundException ex) {
        // Invoice doesn't exist
        javax.swing.JOptionPane.showMessageDialog(this, ex.getMessage(), "Payment Failed", javax.swing.JOptionPane.ERROR_MESSAGE);
        
    } catch (Exception ex) {
        // Any other system error
        javax.swing.JOptionPane.showMessageDialog(this, "System Error: " + ex.getMessage(), "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
    }    
    }//GEN-LAST:event_btnSubmitPaymentActionPerformed

